CREATE TABLE "Student" ("id" VARCHAR(12) NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"bio" TEXT,"isTutor" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Student_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Student_email_key" ON "Student"("email");
CREATE TABLE "Subject" ("id" VARCHAR(12) NOT NULL,"name" TEXT NOT NULL,"category" TEXT NOT NULL,CONSTRAINT "Subject_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Subject_name_key" ON "Subject"("name"); CREATE INDEX "Subject_category_idx" ON "Subject"("category");
CREATE TABLE "StudentSubject" ("id" VARCHAR(12) NOT NULL,"studentId" VARCHAR(12) NOT NULL,"subjectId" VARCHAR(12) NOT NULL,"role" TEXT NOT NULL,CONSTRAINT "StudentSubject_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "StudentSubject_studentId_subjectId_role_key" ON "StudentSubject"("studentId","subjectId","role"); CREATE INDEX "StudentSubject_studentId_idx" ON "StudentSubject"("studentId"); CREATE INDEX "StudentSubject_subjectId_idx" ON "StudentSubject"("subjectId");
CREATE TABLE "StudyGroup" ("id" VARCHAR(12) NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"subjectId" VARCHAR(12) NOT NULL,"maxMembers" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "StudyGroup_pkey" PRIMARY KEY ("id"));
CREATE INDEX "StudyGroup_subjectId_idx" ON "StudyGroup"("subjectId");
CREATE TABLE "StudyGroupMember" ("id" VARCHAR(12) NOT NULL,"studyGroupId" VARCHAR(12) NOT NULL,"studentId" VARCHAR(12) NOT NULL,"joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "StudyGroupMember_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "StudyGroupMember_studyGroupId_studentId_key" ON "StudyGroupMember"("studyGroupId","studentId"); CREATE INDEX "StudyGroupMember_studyGroupId_idx" ON "StudyGroupMember"("studyGroupId"); CREATE INDEX "StudyGroupMember_studentId_idx" ON "StudyGroupMember"("studentId");
CREATE TABLE "Session" ("id" VARCHAR(12) NOT NULL,"studyGroupId" VARCHAR(12) NOT NULL,"startTime" TIMESTAMP(3) NOT NULL,"endTime" TIMESTAMP(3) NOT NULL,"locationOrLink" TEXT NOT NULL,"status" TEXT NOT NULL,CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Session_studyGroupId_idx" ON "Session"("studyGroupId"); CREATE INDEX "Session_studyGroupId_startTime_idx" ON "Session"("studyGroupId","startTime");
CREATE TABLE "Booking" ("id" VARCHAR(12) NOT NULL,"studentId" VARCHAR(12) NOT NULL,"sessionId" VARCHAR(12) NOT NULL,"status" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Booking_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Booking_studentId_idx" ON "Booking"("studentId"); CREATE INDEX "Booking_sessionId_idx" ON "Booking"("sessionId"); CREATE INDEX "Booking_sessionId_status_idx" ON "Booking"("sessionId","status");
CREATE UNIQUE INDEX "Booking_confirmed_student_session_key" ON "Booking"("studentId","sessionId") WHERE "status" = 'confirmed';
ALTER TABLE "StudentSubject" ADD CONSTRAINT "StudentSubject_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "StudentSubject" ADD CONSTRAINT "StudentSubject_subjectId_fkey" FOREIGN KEY ("subjectId") REFERENCES "Subject"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "StudyGroup" ADD CONSTRAINT "StudyGroup_subjectId_fkey" FOREIGN KEY ("subjectId") REFERENCES "Subject"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "StudyGroupMember" ADD CONSTRAINT "StudyGroupMember_studyGroupId_fkey" FOREIGN KEY ("studyGroupId") REFERENCES "StudyGroup"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "StudyGroupMember" ADD CONSTRAINT "StudyGroupMember_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Session" ADD CONSTRAINT "Session_studyGroupId_fkey" FOREIGN KEY ("studyGroupId") REFERENCES "StudyGroup"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Booking" ADD CONSTRAINT "Booking_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Booking" ADD CONSTRAINT "Booking_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "Session"("id") ON DELETE CASCADE ON UPDATE CASCADE;
